import pandas as pd
import numpy as np

# Load the dataset
df = pd.read_csv('chunks_csv/cyclehire_w006.csv')

# Load the adjacency list
adjacency_list = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute the Self-Containment Ratio for each borough
boroughs = df['StartBorough'].unique().tolist()
self_containment_ratios = {}

for borough in boroughs:
    departures = df[(df['StartBorough'] == borough) & (df['EndBorough'] == borough)].shape[0]
    self_contained_trips = df[(df['StartBorough'] == borough) & (df['EndBorough'] == borough)].shape[0]
    self_containment_ratio = self_contained_trips / departures if departures > 0 else 0
    self_containment_ratios[borough] = self_containment_ratio

# Print the Self-Containment Ratios
for borough, ratio in self_containment_ratios.items():
    print(f"Borough {borough} Self-Containment Ratio: {ratio}")

# Identify hot spots and cold spots
hot_spots = []
cold_spots = []

for borough, ratio in self_containment_ratios.items():
    neighbors = adjacency_list[adjacency_list['borough'] == borough]['neighbor'].tolist()
    neighbor_ratios = {}
    for neighbor in neighbors:
        neighbor_ratios[neighbor] = self_containment_ratios.get(neighbor, 0)
    if ratio > 0.5 and all(ratio > 0.5 for r in neighbor_ratios.values()):
        hot_spots.append((borough, ratio))
    elif ratio < 0.2 and all(r < 0.2 for r in neighbor_ratios.values()):
        cold_spots.append((borough, ratio))

# Print the hot spots and cold spots
for hot_spot in hot_spots:
    print(f"Hot Spot: {hot_spot[0]} with Self-Containment Ratio {hot_spot[1]}")
for cold_spot in cold_spots:
    print(f"Cold Spot: {cold_spot[0]} with Self-Containment Ratio {cold_spot[1]}")

# Print the final answer
if hot_spots:
    hot_spots_str = ', '.join([f'{hot_spot[0]} (HH, statistical method={hot_spot[1]})' for hot_spot in hot_spots])
else:
    hot_spots_str = 'none'
if cold_spots:
    cold_spots_str = ', '.join([f'{cold_spot[0]} (LL, statistical method={cold_spot[1]})' for cold_spot in cold_spots])
else:
    cold_spots_str = 'none'
print(f"FINAL ANSWER: {hot_spots_str}, {cold_spots_str}")
